export const REFEPS_SUBMITTED_DISCLAIMER =
  "Identificador enviado vía adapter REFEPS/RENaPDiS según configuración del consultorio. La validez ante farmacias depende de la homologación MSN y firma digital habilitante del profesional — no es una certificación automática de DrFlow.";

