/** Phrases that must not appear as product claims of official validity. */
export const FORBIDDEN_OFFICIAL_PRESCRIPTION_CLAIMS = [
  "receta electrónica oficial",
  "receta electrónica válida ante farmacias",
  "homologado por el ministerio",
  "aprobación gubernamental",
  "validez legal plena garantizada",
] as const;

export function isRefepsSandboxId(refepsId: string | null | undefined): boolean {
  const id = refepsId?.trim().toUpperCase() ?? "";
  return id.startsWith(REFEPS_SANDBOX_ID_PREFIX);
}

export function resolveRefepsDocumentLanguage(input: {
  refepsStatus?: string | null;
  refepsId?: string | null;
}): { qrTitle: string; qrHint: string } | null {
  if (input.refepsStatus !== "submitted" || !input.refepsId?.trim()) return null;

  if (isRefepsSandboxId(input.refepsId)) {
    return {
      qrTitle: "Verificación REFEPS (sandbox / prueba)",
      qrHint: REFEPS_SANDBOX_DISCLAIMER,
    };
  }

  return {
    qrTitle: "Verificación REFEPS (adapter)",
    qrHint: REFEPS_SUBMITTED_DISCLAIMER,
  };
}

export type PrescriptionCompliancePosture = {
  drflowHomologated: false;
  disclaimer: string;
  internalCapabilityCount: number;
  regulatoryItemCount: number;
  notes: string[];
};

export function evaluatePrescriptionCompliancePosture(): PrescriptionCompliancePosture {
  return {
    drflowHomologated: false,
    disclaimer: ARGENTINA_PRESCRIPTION_DISCLAIMER,
    internalCapabilityCount: PRESCRIPTION_INTERNAL_CAPABILITIES.length,
    regulatoryItemCount: PRESCRIPTION_REGULATORY_REQUIREMENTS.length,
    notes: [
      "DrFlow NO está homologado ante REFEPS/RENaPDiS por sí solo.",
      "Emisión interna = borrador / receta local con disclaimer obligatorio.",
      "Sandbox REFEPS no simula aprobación gubernamental (prefijo REFEPS-SBX-).",
      `Etiquetas UI REFEPS: ${REFEPS_STATUS_LABELS.local} / ${REFEPS_STATUS_LABELS.submitted}.`,
      "REQUIERE VERIFICACIÓN profesional legal/regulatoria antes de claims comerciales de e-receta oficial.",
    ],
  };
}
